 ap=argparse.ArgumentParser();ap.add_argument("--root",type=Path,default=Path("."));ap.add_argument("--puckworks-root",type=Path,required=True);ap.add_argument("--output",type=Path,required=True);a=ap.parse_args(argv);root=a.root.resolve();out=(root/a.output).resolve() if not a.output.is_absolute() else a.output;out.mkdir(parents=True,exist_ok=True)
 auth=verify(a.puckworks_root.resolve());base=load(root);auth.update({"ewp_start_head":subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD"],text=True).strip(),"ewp_start_tree":subprocess.check_output(["git","-C",str(root),"rev-parse","HEAD^{tree}"],text=True).strip(),"load_bearing_hashes":file_hashes(root),"change_declarations":["SOURCE_SCENARIO_CHANGE_ONLY","NO_GOVERNING_PHYSICS_CHANGE","NO_PRODUCTION_DEFAULT_CHANGE","NO_RUNTIME_PUCKWORKS_LOCK_CHANGE","NO_SOURCE_ROW_FUSION","NO_HOME_LAB_OPERATION","PHYSICAL_VALIDATION_NOT_ESTABLISHED"]});jsonout(out/"AUTHORITY.json",auth);jsonout(out/"EWP_QUANTITY_DEFINITIONS.json",ledger(base))
 w=wadsworth(a.puckworks_root);fig,figmet,v=vaca(a.puckworks_root,float(base["liquid"]["dynamic_viscosity_Pa_s"]));sup=build(w,figmet,v);jsonout(out/"SOURCE_SUPPORTS.json",sup);csvout(out/"SOURCE_VARIABLE_MAPPING_LEDGER.csv",mapping_build(),FIELDS)
